import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { testSessionUser } from "./_test-helpers";
import { appRouter } from "./routers";
import type { TrpcContext } from "./_core/context";

import { directStorageUrl } from "./_core/publicUrl";
const runIntegration = process.env.RUN_MEDIA_INTEGRATION_TESTS === "1";
const maybeDescribe = runIntegration ? describe : describe.skip;
const slotKey = "home-hero" as const;
// A real 4x4 PNG generated by sharp and verified against the full
// processUploadedImage pipeline (not just a magic-byte/metadata check) —
// see the matching comment in profile.integration.test.ts for why that
// distinction matters: uploadSiteMediaImage now actually decodes+re-encodes
// via sharp, and a fixture that only "looks like" a valid PNG header fails
// there with a real libpng error even though sharp's .metadata() accepts it.
const onePixelPng = "iVBORw0KGgoAAAANSUhEUgAAAAQAAAAECAYAAACp8Z5+AAAACXBIWXMAAAPoAAAD6AG1e1JrAAAAEklEQVQImWM4IWf0HxkzkC4AAGuYIXGU5TmSAAAAAElFTkSuQmCC";

function createAdminContext(): TrpcContext {
  return {
    user: testSessionUser({
      id: 1,
      email: "owner@example.com",
      name: "Site Media Integration Admin",
      role: "admin",
      emailVerifiedAt: null,
      sessionVersion: 0,
      createdAt: new Date(),
      updatedAt: new Date(),
      lastSignedIn: new Date(),
    }),
    req: { protocol: "https", headers: {} } as unknown as TrpcContext["req"],
    res: { clearCookie: () => undefined } as unknown as TrpcContext["res"],
  };
}

maybeDescribe("managed site-media integration", () => {
  const adminCaller = appRouter.createCaller(createAdminContext());
  const publicCaller = appRouter.createCaller({ ...createAdminContext(), user: null });

  // home-hero is a REAL, admin-editable production slot (Home.tsx's hero
  // banner) -- not a throwaway test fixture. A previous version of this
  // test unconditionally cleared it in afterEach, which meant every local
  // run of the full suite with RUN_MEDIA_INTEGRATION_TESTS=1 silently wiped
  // out whatever real photo an admin had actually uploaded for the
  // homepage hero (this is exactly what happened once — see docs/PROJECT-GUIDE.md/
  // HISTORY.md's "orphaned R2 upload" incident). Snapshot-and-restore
  // instead of destroy-and-leave-empty: capture whatever's really there
  // before the test runs, put it back afterward no matter what the test did.
  let originalHomeHero: { imageUrl: string; altText: string | null } | undefined;

  beforeEach(async () => {
    const before = await adminCaller.admin.siteMedia();
    const existing = before.find(media => media.slotKey === slotKey);
    originalHomeHero = existing ? { imageUrl: existing.imageUrl, altText: existing.altText } : undefined;
  });

  afterEach(async () => {
    if (originalHomeHero) {
      await adminCaller.admin.updateSiteMedia({ slotKey, imageUrl: originalHomeHero.imageUrl, altText: originalHomeHero.altText }).catch(() => undefined);
    } else {
      await adminCaller.admin.clearSiteMedia({ slotKey }).catch(() => undefined);
    }
  });

  it("uploads a managed image, exposes its persisted public override, and removes it on reset", async () => {
    const upload = await adminCaller.admin.uploadSiteMediaImage({
      fileName: "media-integration.png",
      contentType: "image/png",
      dataBase64: onePixelPng,
    });
    expect(upload.url).toContain("site-media");

    await adminCaller.admin.updateSiteMedia({ slotKey, imageUrl: upload.url, altText: "Integration media check" });
    const publicMedia = await publicCaller.content.siteMedia();
    // 2026-09-21: storefront-д R2-ийн шууд хаяг очдог (publicUrl.ts-ийн directStorageUrl);
    // admin.siteMedia нь `/cdn/` хэвээр. Хоёр хэлбэр нэг key рүү заана.
    expect(publicMedia.find(media => media.slotKey === slotKey)).toMatchObject({ imageUrl: directStorageUrl(upload.url), altText: "Integration media check" });

    await adminCaller.admin.clearSiteMedia({ slotKey });
    const resetMedia = await publicCaller.content.siteMedia();
    expect(resetMedia.find(media => media.slotKey === slotKey)).toBeUndefined();
  });
});
